import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd(); fz = repo / 'target/debug/fz'

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run([str(fz), 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

def find_message(payload, needle):
    return next(item for item in payload['items'] if needle in item['message'])

alias_use_after_free = verify('alias_use_after_free', '''
    fn main() -> i32 {
        let p = alloc(32)
        let q = p
        free(p)
        close(q)
        return 0
    }
''', 1)
alias_diag = find_message(alias_use_after_free, 'uses value `q` after provenance root 1 was freed')
assert 'fresh owned value before reuse' in (alias_diag.get('help') or ''), alias_diag

helper_provenance = verify('helper_provenance', '''
    fn first(a: *mut u8, b: *mut u8) -> *mut u8 {
        return a
    }
    fn second(a: *mut u8, b: *mut u8) -> *mut u8 {
        return b
    }
    fn main() -> i32 {
        let a = alloc(32)
        let b = alloc(32)
        let from_first = first(a, b)
        let from_second = second(a, b)
        free(a)
        close(from_first)
        close(from_second)
        free(b)
        return 0
    }
''', 1)
assert any('uses value `from_first` after provenance root 1 was freed' in message for message in messages(helper_provenance)), helper_provenance
assert not any('uses value `from_second` after provenance root' in message for message in messages(helper_provenance)), helper_provenance

tuple_provenance = verify('tuple_provenance', '''
    fn main() -> i32 {
        let a = alloc(32)
        let b = alloc(32)
        let (left, right) = (a, b)
        free(a)
        close(left)
        close(right)
        free(b)
        return 0
    }
''', 1)
assert any('uses value `left` after provenance root 1 was freed' in message for message in messages(tuple_provenance)), tuple_provenance
assert not any('uses value `right` after provenance root' in message for message in messages(tuple_provenance)), tuple_provenance

struct_provenance = verify('struct_provenance', '''
    struct Pair { left: *mut u8, right: *mut u8 }
    fn main() -> i32 {
        let a = alloc(32)
        let b = alloc(32)
        let Pair { left, right } = Pair { left: a, right: b }
        free(a)
        close(left)
        close(right)
        free(b)
        return 0
    }
''', 1)
assert any('uses value `left` after provenance root 1 was freed' in message for message in messages(struct_provenance)), struct_provenance
assert not any('uses value `right` after provenance root' in message for message in messages(struct_provenance)), struct_provenance

reassignment_pass = verify('reassignment_pass', '''
    ext unsafe c fn acquire_owned() -> *u8
    unsafe fn main() -> i32 {
        let p = alloc(32)
        let q = p
        q = acquire_owned()
        free(p)
        close(q)
        return 0
    }
''', 0)
assert reassignment_pass['errors'] == 0, reassignment_pass
assert not any('after provenance root' in message for message in messages(reassignment_pass)), reassignment_pass

returned_second_pass = verify('returned_second_pass', '''
    fn passthrough(a: *mut u8, b: *mut u8) -> *mut u8 {
        return b
    }
    fn main() -> i32 {
        let a = alloc(32)
        let b = alloc(32)
        let ret = passthrough(a, b)
        free(a)
        close(ret)
        free(b)
        return 0
    }
''', 0)
assert returned_second_pass['errors'] == 0, returned_second_pass
assert not any('uses value `ret` after provenance root' in message for message in messages(returned_second_pass)), returned_second_pass

nested_control_flow = verify('nested_control_flow', '''
    fn main() -> i32 {
        let p = alloc(32)
        let q = p
        if true {
            free(p)
        } else {
            return 0
        }
        close(q)
        return 0
    }
''', 1)
nested_diag = find_message(nested_control_flow, 'uses value `q` after provenance root 1 was freed')
assert 'fresh owned value before reuse' in (nested_diag.get('help') or ''), nested_diag

print('compiler-memory-provenance-ok')

